using MediatR;using OAS.Application.Abstractions.Persistence;using OAS.Application.Common.Exceptions;using OAS.Contracts.Accounting.Currencies;using OAS.Domain.Accounting.Entities;
namespace OAS.Application.Accounting.Currencies.Queries.GetCurrencyById;public sealed class GetCurrencyByIdQueryHandler(IReadRepository<Currency,Guid> repository):IRequestHandler<GetCurrencyByIdQuery,CurrencyDto>{public async Task<CurrencyDto> Handle(GetCurrencyByIdQuery r,CancellationToken ct){var e=await repository.GetByIdAsync(r.Id,ct)??throw new NotFoundException(nameof(Currency),r.Id);return new(e.Id,e.Code,e.NameAr,e.NameEn,e.Symbol,e.DecimalPlaces,e.IsActive,Convert.ToBase64String(e.RowVersion));}}
